export type CatalogSource =
    | 'repository'
    | 'beatstars-api'
    | 'beatstars-export'
    | 'owner-csv'
    | 'verified-public-page'
    | 'track-widget-generator'
    | 'owner-provided'
    | 'inferred'
    | 'unverified'
    | 'unspecified';

export type IdentityVerificationStatus =
    | 'unverified'
    | 'track-id-extracted'
    | 'title-verified'
    | 'mismatch';

export type OfferVerificationStatus =
    | 'unverified'
    | 'product-page-active'
    | 'unavailable'
    | 'sold'
    | 'verification-failed';

export type MetadataVerificationStatus =
    | 'unverified'
    | 'owner-confirmed'
    | 'public-source-confirmed';

export type SeoStatus = 'draft' | 'noindex' | 'indexable';

export type BeatAvailability =
    | 'available'
    | 'sold'
    | 'exclusive-only'
    | 'unavailable'
    | 'unknown';

export interface LocalizedText {
    'en-US'?: string;
    'en-GB'?: string;
    'de-DE'?: string;
    'ja-JP'?: string;
}

export interface BeatLicense {
    id: string;
    name: string;
    price: string;
    priceValue: number;
    currency: string;
    type?: 'non-exclusive' | 'exclusive';
    includes?: string[];
    fileFormats: string[];
    includesStems: boolean;
    commercialUse: boolean;
    streamingLimit: string;
    salesLimit: string;
    musicVideoLimit: string;
    radioStationsLimit?: string;
    paidPerformances: boolean;
    contentIdAllowed: boolean;
    creditRequired: boolean;
    creditString: string;
    source: CatalogSource;
}

export interface BeatProduct {
    id: string;
    slug: string;
    title: string;
    localizedTitle?: LocalizedText;
    producer: 'Virzy Guns';
    primaryGenre: string;
    subgenres: string[];
    moods: string[];
    tags: string[];
    durationSeconds?: number;
    coverImageUrl?: string;
    previewAudioUrl?: string;
    beatstarsProductUrl: string;
    beatstarsTrackId: string;
    beatstarsEmbedUrl: string;
    licenses: BeatLicense[];
    availability: BeatAvailability;
    description: LocalizedText;
    releaseDate?: string;
    updatedAt?: string;
    identityVerification: IdentityVerificationStatus;
    offerVerification: OfferVerificationStatus;
    metadataVerification: MetadataVerificationStatus;
    seoStatus: SeoStatus;
    sources: Record<string, CatalogSource>;
}

export interface CategoryDef {
    slug: string;
    name: string;
    localizedName: LocalizedText;
    shortDescription: LocalizedText;
    fullDescription: LocalizedText;
    keywords: {
        'en-US': string[];
        'de-DE': string[];
        'ja-JP': string[];
    };
    primaryGenre: string;
    subgenres: string[];
    soundCharacter: LocalizedText;
    recommendedVocalFit: LocalizedText;
}

const formatCatalogLimit = (
    value: number | null,
    unlimited: boolean,
    singular: string,
    plural: string,
): string => {
    if (unlimited) return `UNLIMITED ${plural}`;
    if (value === null) return `Unconfirmed ${plural}`;
    return `${value.toLocaleString('en-US')} ${value === 1 ? singular : plural}`;
};

const formatIncludedFile = (format: string): string => {
    if (format.startsWith('MP3')) return 'MP3 File';
    if (format.startsWith('WAV')) return 'WAV File';
    return format;
};

/** Standard Non-Exclusive Licenses, generated from the canonical registry. */
export const defaultLicenses: BeatLicense[] = PUBLIC_CONFIRMED_LICENSES.map((tier) => ({
    id: tier.catalogId,
    name: tier.name,
    price: tier.priceUsd === null ? 'Contact' : `$${tier.priceUsd}`,
    priceValue: tier.priceUsd ?? 0,
    currency: 'USD',
    type: 'non-exclusive',
    includes: tier.fileFormats.map(formatIncludedFile),
    fileFormats: [...tier.fileFormats],
    includesStems: tier.includesStems === true,
    commercialUse: tier.commercialUse === true,
    streamingLimit: formatCatalogLimit(
        tier.onlineAudioStreams,
        tier.unlimitedOnlineAudioStreams,
        'Stream',
        'Streams',
    ),
    salesLimit: formatCatalogLimit(
        tier.distributionCopies,
        tier.unlimitedDistribution,
        'Copy',
        'Copies',
    ),
    musicVideoLimit: formatCatalogLimit(tier.musicVideos, false, 'Music Video', 'Music Videos'),
    radioStationsLimit: formatCatalogLimit(tier.radioStations, false, 'Station', 'Stations'),
    paidPerformances: tier.paidPerformances === true,
    contentIdAllowed: tier.contentIdAllowed === true,
    creditRequired: tier.creditRequired === true,
    creditString: tier.creditString ?? '',
    source: 'owner-provided',
}));

